import React, { useState } from 'react';
import './Navbar.css';

const NAV_LINKS = [
  { label: 'Work', href: '#work' },
  { label: 'Skills', href: '#skills' },
  { label: 'Projects', href: '#projects' },
  { label: 'About', href: '#about' },
];

export default function Navbar() {
  const [menuOpen, setMenuOpen] = useState(false);

  return (
    <header className="navbar sticky top-0 z-50 bg-white border-b border-black">
      <div className="navbar__inner h-16 pl-4 flex items-center justify-between lg:pl-12 lg:h-20">
        {/* Logo */}
        <a href="/" className="navbar__logo font-display font-bold text-xl tracking-tight">
          KS<span className="text-primary">.</span>
        </a>

        {/* Desktop Nav */}
        <div className="navbar__desktop hidden md:flex items-center">
          <nav className="flex gap-8 px-8 lg:gap-12 lg:px-12">
            {NAV_LINKS.map((link) => (
              <a
                key={link.label}
                href={link.href}
                className="nav-link font-mono font-semibold text-sm uppercase leading-tight xl:text-base hover:text-primary transition-colors"
              >
                {link.label}
              </a>
            ))}
          </nav>
          <a href="#contact" className="navbar__cta hidden md:block bg-primary h-16 px-8 font-mono font-semibold text-sm uppercase leading-tight xl:text-base whitespace-nowrap flex items-center justify-center hover:bg-primary-600 transition-colors lg:h-20">
            Get In Touch
          </a>
        </div>

        {/* Mobile buttons */}
        <div className="flex items-center md:hidden">
          <button
            className="hamburger bg-white text-black inline-flex items-center justify-center h-16 px-4 cursor-pointer hover:ring-2 hover:ring-inset hover:ring-black"
            onClick={() => setMenuOpen(!menuOpen)}
            aria-label="Toggle menu"
          >
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
              {menuOpen ? (
                <path fill="currentColor" d="M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z" />
              ) : (
                <path fill="currentColor" d="M3 6h18v2H3zm0 5h18v2H3zm0 5h18v2H3z" />
              )}
            </svg>
          </button>
          <a href="#contact" className="bg-primary text-black border-l inline-flex items-center justify-center h-16 px-4 cursor-pointer hover:ring-2 hover:ring-inset hover:ring-black">
            <svg width="24" height="24" viewBox="0 0 24 24">
              <path fill="currentColor" d="M20 4H4c-1.1 0-2 .9-2 2v12c0 1.1.9 2 2 2h16c1.1 0 2-.9 2-2V6c0-1.1-.9-2-2-2zm0 4l-8 5-8-5V6l8 5 8-5v2z" />
            </svg>
          </a>
        </div>
      </div>

      {/* Mobile Menu */}
      {menuOpen && (
        <nav className="navbar__mobile md:hidden bg-white border-t border-black">
          {NAV_LINKS.map((link) => (
            <a
              key={link.label}
              href={link.href}
              className="block px-6 py-4 font-mono font-semibold text-sm uppercase border-b border-black hover:bg-gray-50"
              onClick={() => setMenuOpen(false)}
            >
              {link.label}
            </a>
          ))}
          <a
            href="#contact"
            className="block px-6 py-4 font-mono font-semibold text-sm uppercase bg-primary text-black hover:bg-primary-600"
            onClick={() => setMenuOpen(false)}
          >
            Get In Touch →
          </a>
        </nav>
      )}
    </header>
  );
}
